/**************************************************************************************************
 * DP (ID = 0x0) Descriptor Definitions
 **************************************************************************************************/

/**************************************************************************************************/
#define Reg_DPT_REG0_Aux_2m_Duration_BitField_MaxValue                          ((1u << 6 ) - 1)
#define Reg_DPT_REG0_Ephy_Sw_Active_BitField_MaxValue                           ((1u << 1 ) - 1)
#define Reg_DPT_REG0_Adaptive_Sync_Spec_Version_BitField_MaxValue               ((1u << 1 ) - 1)
#define Reg_DPT_REG0_Lt_Max_Bandwith_Policy_BitField_MaxValue                   ((1u << 1 ) - 1)
#define Reg_DPT_REG0_Msa_Send_Pos_BitField_MaxValue                             ((1u << 1 ) - 1)
#define Reg_DPT_REG0_Phy_Cts_Mode_BitField_MaxValue                             ((1u << 1 ) - 1)
#define Reg_DPT_REG0_Sw_Hpd_BitField_MaxValue                                   ((1u << 1 ) - 1)
#define Reg_DPT_REG0_Hpd_Min_Mode_BitField_MaxValue                             ((1u << 2 ) - 1)
#define Reg_DPT_REG0_Sr_Duration_BitField_MaxValue                              ((1u << 9 ) - 1)
#define Reg_DPT_REG0_Scramble_Disable_BitField_MaxValue                         ((1u << 1 ) - 1)
#define Reg_DPT_REG0_En_Audio_Timestamp_BitField_MaxValue                       ((1u << 1 ) - 1)
#define Reg_DPT_REG0_Audio_En_BitField_MaxValue                                 ((1u << 1 ) - 1)
#define Reg_DPT_REG0_Adaptive_Sync_Pos_BitField_MaxValue                        ((1u << 2 ) - 1)
#define Reg_DPT_REG0_Adaptive_En_BitField_MaxValue                              ((1u << 1 ) - 1)
#define Reg_DPT_REG0_Enhance_Mod_BitField_MaxValue                              ((1u << 1 ) - 1)
#define Reg_DPT_REG0_Dp_Alternate_BitField_MaxValue                             ((1u << 1 ) - 1)
#define Reg_DPT_REG0_Dpt_Enable_BitField_MaxValue                               ((1u << 1 ) - 1)
/**************************************************************************************************/

/**************************************************************************************************/
typedef union {
    unsigned int uint;
    struct {
        unsigned int Aux_2m_Duration                        : 6 ;  // the half of 2m clk duration ie: 24 when ref clk is 25M 26 when ref clk is 27M
        unsigned int Ephy_Sw_Active                         : 1 ;  // ephy ready when sw control ephy power
        unsigned int Adaptive_Sync_Spec_Version             : 1 ;  // 0: intital spec that the HB2 is 01h 1: SCR spec that the HBR2 is 00h
        unsigned int Lt_Max_Bandwith_Policy                 : 1 ;  // linktraining fallback sequnce 0: not max bandwith policy (HBR3->HBR2->HBR1->RBR，4Lane-2Lane-1Lane) 1: lt_max_bandwith_policy HBR3 4L-> HBR2 4L -> HBR3 2L ->HBR2 2L->….
        unsigned int Msa_Send_Pos                           : 1 ;  // msa_send_pos 0:at the end of vden 1: at the begin of vsync
        unsigned int Phy_Cts_Mode                           : 1 ;  // phy cts mode enable
        unsigned int Sw_Hpd                                 : 1 ;  // sw hot plug
        unsigned int Hpd_Min_Mode                           : 2 ;  // hpd low period select
        unsigned int Sr_Duration                            : 9 ;  // the number of BS which will be replaced by SR(default 512)
        unsigned int Scramble_Disable                       : 1 ;  // dpt disable scramble function
        unsigned int En_Audio_Timestamp                     : 1 ;  // dpt enable audio timestamp sdp
        unsigned int Audio_En                               : 1 ;  // dpt audio enable
        unsigned int Adaptive_Sync_Pos                      : 2 ;  // adaptive sync sdp postion select
        unsigned int Adaptive_En                            : 1 ;  // dpt adaptive sync mode
        unsigned int Enhance_Mod                            : 1 ;  // dpt enhaced mode
        unsigned int Dp_Alternate                           : 1 ;  // dpt discramble alternate mode
        unsigned int Dpt_Enable                             : 1 ;  // dpt enable
    } reg;
} Reg_Dpt_Reg0;
/**************************************************************************************************/

/**************************************************************************************************/
#define Reg_DPT_REG1_Linkrate_Set_Cfg3_BitField_MaxValue                        ((1u << 8 ) - 1)
#define Reg_DPT_REG1_Linkrate_Set_Cfg2_BitField_MaxValue                        ((1u << 8 ) - 1)
#define Reg_DPT_REG1_Linkrate_Set_Cfg1_BitField_MaxValue                        ((1u << 8 ) - 1)
#define Reg_DPT_REG1_Linkrate_Set_Cfg0_BitField_MaxValue                        ((1u << 8 ) - 1)
/**************************************************************************************************/

/**************************************************************************************************/
typedef union {
    unsigned int uint;
    struct {
        unsigned int Linkrate_Set_Cfg3                      : 8 ;  // link rate 3 config value (default 8.1G = 1eh x 270M)
        unsigned int Linkrate_Set_Cfg2                      : 8 ;  // link rate 2 config value (default 5.4G = 14h x 270M)
        unsigned int Linkrate_Set_Cfg1                      : 8 ;  // link rate 1 config value (default 2.7G = 0ah x 270M)
        unsigned int Linkrate_Set_Cfg0                      : 8 ;  // link rate 0 config value (default 1.62G = 06h x 270M)
    } reg;
} Reg_Dpt_Reg1;
/**************************************************************************************************/

/**************************************************************************************************/
#define Reg_DPT_REG2_Eq_Interval_BitField_MaxValue                              ((1u << 16) - 1)
#define Reg_DPT_REG2_Cr_Interval_BitField_MaxValue                              ((1u << 16) - 1)
/**************************************************************************************************/

/**************************************************************************************************/
typedef union {
    unsigned int uint;
    struct {
        unsigned int Eq_Interval                            : 16;  // dp linktraining eq phase duration( unit:us default 400us)
        unsigned int Cr_Interval                            : 16;  // dp linktraining cr phase duration( unit:us default 400us)
    } reg;
} Reg_Dpt_Reg2;
/**************************************************************************************************/

/**************************************************************************************************/
#define Reg_DPT_REG3_Lt_Start_BitField_MaxValue                                 ((1u << 1 ) - 1)
#define Reg_DPT_REG3_Lt_Rst_BitField_MaxValue                                   ((1u << 1 ) - 1)
#define Reg_DPT_REG3_Force_Lt_Pass_BitField_MaxValue                            ((1u << 1 ) - 1)
#define Reg_DPT_REG3_Linkrate_Set_Use_BitField_MaxValue                         ((1u << 1 ) - 1)
#define Reg_DPT_REG3_Lt_Rate_BitField_MaxValue                                  ((1u << 2 ) - 1)
#define Reg_DPT_REG3_Lt_Lane_Num_Force_BitField_MaxValue                        ((1u << 1 ) - 1)
#define Reg_DPT_REG3_Lt_Lane_Num_BitField_MaxValue                              ((1u << 2 ) - 1)
#define Reg_DPT_REG3_Eq_Pat_BitField_MaxValue                                   ((1u << 2 ) - 1)
#define Reg_DPT_REG3_Lt_Link_Enable_BitField_MaxValue                           ((1u << 1 ) - 1)
#define Reg_DPT_REG3_Send_First_Msa_BitField_MaxValue                           ((1u << 1 ) - 1)
#define Reg_DPT_REG3_Dprx_Recv_Clk_Out_En_BitField_MaxValue                     ((1u << 1 ) - 1)
#define Reg_DPT_REG3_Retry_Lt_Clear_Dpcd102_BitField_MaxValue                   ((1u << 1 ) - 1)
#define Reg_DPT_REG3_Clear_Dpcd102_When_Fail_BitField_MaxValue                  ((1u << 1 ) - 1)
#define Reg_DPT_REG3_Voltage_Pre_Set_BitField_MaxValue                          ((1u << 2 ) - 1)
#define Reg_DPT_REG3_Emphasis_Pre_Set_BitField_MaxValue                         ((1u << 2 ) - 1)
#define Reg_DPT_REG3_Max_Swing_Support_BitField_MaxValue                        ((1u << 2 ) - 1)
#define Reg_DPT_REG3_Max_Emphasis_Support_BitField_MaxValue                     ((1u << 2 ) - 1)
#define Reg_DPT_REG3_Interval_1us_BitField_MaxValue                             ((1u << 8 ) - 1)
/**************************************************************************************************/

/**************************************************************************************************/
typedef union {
    unsigned int uint;
    struct {
        unsigned int Lt_Start                               : 1 ;  // enable dp link traning,this register will be auto clear by hw when finished link-training
        unsigned int Lt_Rst                                 : 1 ;  // reset dp link training function
        unsigned int Force_Lt_Pass                          : 1 ;  // force HW turn to Link-training pass mode(used when sw link-training)
        unsigned int Linkrate_Set_Use                       : 1 ;  // dprx use the dpcd100(LINK_BW_SET) as Main-Link Bandwidth Setting
        unsigned int Lt_Rate                                : 2 ;  // the initial link rate when link traning
        unsigned int Lt_Lane_Num_Force                      : 1 ;  // lane number force enable
        unsigned int Lt_Lane_Num                            : 2 ;  // the initial lane number when link training or the forced lane number when lane_num force enable
        unsigned int Eq_Pat                                 : 2 ;  // the EQ training pattern select
        unsigned int Lt_Link_Enable                         : 1 ;  // force the main link output when sw link training(does not need when hardware link training)
        unsigned int Send_First_Msa                         : 1 ;  // the dp will send the msa before the active video at the first frame
        unsigned int Dprx_Recv_Clk_Out_En                   : 1 ;  // the config value for dpcd102[4](RECOVERED_CLOCK_OUT_EN)
        unsigned int Retry_Lt_Clear_Dpcd102                 : 1 ;  // HW will clear dpcd102 (link training pattern) when retry link training
        unsigned int Clear_Dpcd102_When_Fail                : 1 ;  // HW will clear dpcd102 (link training pattern) when failed link training
        unsigned int Voltage_Pre_Set                        : 2 ;  // the initial value of voltage when start link training
        unsigned int Emphasis_Pre_Set                       : 2 ;  // the initial value of emphasis when start link training
        unsigned int Max_Swing_Support                      : 2 ;  // the max swing value dp support(default 'h3)
        unsigned int Max_Emphasis_Support                   : 2 ;  // the max emphasis value dp support(default 'h3)
        unsigned int Interval_1us                           : 8 ;  // the config value for 1us timer counter( default value = 27 for 27M ref clk)
    } reg;
} Reg_Dpt_Reg3;
/**************************************************************************************************/

/**************************************************************************************************/
#define Reg_DPT_REG4_Aux_Retry_Max_BitField_MaxValue                            ((1u << 4 ) - 1)
#define Reg_DPT_REG4_Pre_Sync_Len_BitField_MaxValue                             ((1u << 8 ) - 1)
#define Reg_DPT_REG4_Total_Retry_Max_BitField_MaxValue                          ((1u << 6 ) - 1)
#define Reg_DPT_REG4_Fec_Parity_Ph_Flsr_Enable_BitField_MaxValue                ((1u << 1 ) - 1)
#define Reg_DPT_REG4_Fec_Ctrl_Code_Flsr_Enable_BitField_MaxValue                ((1u << 1 ) - 1)
#define Reg_DPT_REG4_Same_Set_Retry_Max_BitField_MaxValue                       ((1u << 6 ) - 1)
#define Reg_DPT_REG4_Fec_Org_Version_BitField_MaxValue                          ((1u << 1 ) - 1)
#define Reg_DPT_REG4_Fec_En_BitField_MaxValue                                   ((1u << 1 ) - 1)
#define Reg_DPT_REG4_Eq_Loop_Max_BitField_MaxValue                              ((1u << 4 ) - 1)
/**************************************************************************************************/

/**************************************************************************************************/
typedef union {
    unsigned int uint;
    struct {
        unsigned int Aux_Retry_Max                          : 4 ;  // the config value for dp aux retry max counter
        unsigned int Pre_Sync_Len                           : 8 ;  // the config value for DP aux tx pre sync length( the value must be odd)
        unsigned int Total_Retry_Max                        : 6 ;  // the config value for total loop counter when link-training
        unsigned int Fec_Parity_Ph_Flsr_Enable              : 1 ;  // accroding to the spec ,the lfsr should be hold when fec_parity_ph, value 1 for debug
        unsigned int Fec_Ctrl_Code_Flsr_Enable              : 1 ;  // accroding to the spec ,the lfsr should be hold when fec_decode_en or fec_decode_dis, value 1 for debug
        unsigned int Same_Set_Retry_Max                     : 6 ;  // the config value for loop counter of same setting when link-training
        unsigned int Fec_Org_Version                        : 1 ;  // 1: when DP sink is dp1.4 or lower 0:DP sink is dp 1.4A
        unsigned int Fec_En                                 : 1 ;  // fec function enable
        unsigned int Eq_Loop_Max                            : 4 ;  // the config value for max loop of eq phase
    } reg;
} Reg_Dpt_Reg4;
