#define Reg_DPT_REG5_Aux_Val_Flag_BitField_MaxValue                             ((1u << 1 ) - 1)
#define Reg_DPT_REG5_Sw_Aux_Timeout_Flag_BitField_MaxValue                      ((1u << 1 ) - 1)
