#define Reg_DPT_REG5_Aux_Wait_Duration_BitField_MaxValue                        ((1u << 8 ) - 1)
#define Reg_DPT_REG5_Sync_Min_BitField_MaxValue                                 ((1u << 6 ) - 1)
#define Reg_DPT_REG5_Sync_Max_BitField_MaxValue                                 ((1u << 6 ) - 1)
