/**************************************************************************************************/
typedef union {
    unsigned int uint;
    struct {
        unsigned int Aux_Req                                : 1 ;  // sw aux tx request(will be auto clear when aux tx finish)
        unsigned int Aux_Val_Flag                           : 1 ;  // read back aux valid,Hw set the register to 1 , SW need to clear the register after read back aux data
        unsigned int Sw_Aux_Timeout_Flag                    : 1 ;  // sw aux request aux 400us timeout(write 0 clear )
        unsigned int Hw_Aux_Timout_Flag                     : 1 ;  // hw aux request aux 400us timeout(write 0 clear )
        unsigned int Aux_Num                                : 5 ;  // sw aux tx data total byte(aux_len 1byte + N byte aux data)
        unsigned int Aux_Ephy_Start                         : 1 ;  // Enable aux ephy
        unsigned int En_Auxlong_Time_Hpd_Irq                : 1 ;  // enable aux reply timer to 3.2ms when detect HPD IRQ( dp spec1.4mem ,2.8.2)
        unsigned int Auxlong_For_Wake_Sink                  : 1 ;  // reserved_1
        unsigned int Aux_Wait_Duration                      : 8 ;  // the duration between 2 aux tx request(unit: ref clk)
        unsigned int Sync_Min                               : 6 ;  // the min value for the dp aux rx pre-sync length (6'h0 ,disable check the pre-sync length min value)
        unsigned int Sync_Max                               : 6 ;  // the max value for the dp aux rx pre-sync length (6'h3F ,disable check the pre-sync length max value)
    } reg;
} Reg_Dpt_Reg5;
