typedef union {
    unsigned int uint;
    struct {
        unsigned int Psr_Ml_Sleep_Num                       : 3 ;  // the number of ML_PHY_SLEEP
        unsigned int Ml_Sleep_Req                           : 1 ;  // sw send an ML_PHY_SLEEP or ML_PHY_STANDY pattern
        unsigned int Psr_Crc_Valid_O                        : 1 ;  // hw calculated crc value valid
        unsigned int Psr_Burst_Update_Start                 : 1 ;  // show that the burst updated is start , the sw can updated the next active frame, write 1 to clear
        unsigned int Psr_Frame_Start_Sel                    : 1 ;  // select the positon which to send the vcs frame 0: at the end of the vden 1: at the begin of vsync
        unsigned int Psr_Reactive_Idle_Pat_Num              : 7 ;  // the IDLE pattern num of psr main link on(from off state to on state)
        unsigned int Psr_Ml_Sleep_Type                      : 1 ;  // 0: ML_PHY_SLEEP 1:ML_PHY_STANDY
        unsigned int Psr_Send_Ml_Sleep                      : 1 ;  // hw will send ML_PHY_SLEEP or ML_PHY_STANDY when ml off on the fec enable mode 0: send 1: not send
        unsigned int Psr_Force_State                        : 4 ;  // psr force state
        unsigned int Psr_Force                              : 1 ;  // psr state force enable
        unsigned int Psr_Exit                               : 1 ;  // psr state exit request
        unsigned int Psr_Reactive_Mode                      : 1 ;  // 0: restart link training when main link on 1: send 5 idle patten when main link on
        unsigned int Psr_Sleep                              : 1 ;  // psr state sleep request
        unsigned int Psr_Update_Mode                        : 1 ;  // psr updated mode
        unsigned int Psr_Update                             : 1 ;  // psr updated request
        unsigned int Psr_Enter_Mode                         : 1 ;  // psr enter mode
        unsigned int Psr_Enter                              : 1 ;  // psr enter request
        unsigned int Psr_Crc_En                             : 1 ;  // psr crc enable
        unsigned int Psr_Burst_Update                       : 1 ;  // psr updated burst mode
        unsigned int Psr_Ml_On                              : 1 ;  // psr will remain mainlink on when enter psr
        unsigned int Psr_En                                 : 1 ;  // psr enable
    } reg;
} Reg_Dpt_Reg26;
